window.GLOSSAIRE = {"action": {"t": "Action", "d": "Titre de propriété représentant une part du capital d'une entreprise. Il peut donner droit à une part des bénéfices (dividende) et à un droit de vote.", "c": "marches", "en": "Share / Stock"}, "indice-boursier": {"t": "Indice boursier", "d": "Panier d'actions dont la valeur résume l'évolution d'un marché ou d'un secteur. Il se trade via des ETF, des futures ou des CFD, pas directement.", "c": "marches", "en": "Stock index"}, "cac-40": {"t": "CAC 40", "d": "Principal indice de la Bourse de Paris, composé de 40 grandes sociétés, pondéré par la capitalisation flottante avec un plafond de 15 % par valeur. C'est un indice de prix (dividendes non réinvestis).", "c": "marches", "en": "CAC 40"}, "sp-500": {"t": "S&P 500", "d": "Indice des 500 plus grandes entreprises américaines cotées, pondéré par la capitalisation flottante. Référence mondiale des actions.", "c": "marches", "en": "S&P 500"}, "euro-stoxx-50": {"t": "Euro Stoxx 50", "d": "Indice de 50 grandes sociétés de la zone euro. Il sert de sous-jacent à des contrats à terme très échangés (10 € par point).", "c": "marches", "en": "Euro Stoxx 50"}, "dax": {"t": "DAX", "d": "Principal indice de la Bourse de Francfort (40 valeurs allemandes). Contrairement au CAC 40, c'est un indice de rendement (dividendes réinvestis).", "c": "marches", "en": "DAX"}, "nasdaq": {"t": "Nasdaq", "d": "Bourse électronique américaine très orientée technologie, et par extension ses indices (Nasdaq Composite, Nasdaq 100).", "c": "marches", "en": "Nasdaq"}, "nyse": {"t": "NYSE", "d": "New York Stock Exchange, la plus grande bourse d'actions du monde par capitalisation. Séance principale de 9 h 30 à 16 h, heure de New York.", "c": "marches", "en": "New York Stock Exchange"}, "euronext": {"t": "Euronext", "d": "Opérateur boursier européen qui gère notamment les bourses de Paris, Amsterdam, Bruxelles, Lisbonne, Dublin, Oslo et Milan.", "c": "marches", "en": "Euronext"}, "indice-dividendes-reinvestis": {"t": "Indice dividendes réinvestis", "d": "Version d'un indice qui réinvestit les dividendes versés, et mesure donc le rendement total. Variantes : brut (GR) ou net de retenues fiscales (NR).", "c": "marches", "en": "Total return index"}, "ponderation-capitalisation": {"t": "Pondération par la capitalisation", "d": "Méthode de construction d'indice où chaque société pèse en proportion de sa capitalisation boursière (souvent flottante). Les plus grosses dominent.", "c": "marches", "en": "Market-cap weighting"}, "obligation": {"t": "Obligation", "d": "Titre de dette : l'émetteur emprunte, verse des intérêts (coupons) et rembourse le nominal à l'échéance. Son prix varie à l'inverse des taux d'intérêt.", "c": "marches", "en": "Bond"}, "coupon": {"t": "Coupon", "d": "Intérêt périodique versé au porteur d'une obligation, exprimé en pourcentage du nominal.", "c": "marches", "en": "Coupon"}, "nominal": {"t": "Nominal (valeur nominale)", "d": "Montant de référence d'une obligation, remboursé à l'échéance et servant au calcul des coupons.", "c": "marches", "en": "Face value / Par value"}, "rendement-obligataire": {"t": "Rendement obligataire", "d": "Taux de rendement d'une obligation compte tenu de son prix de marché, de ses coupons et de son remboursement. Il évolue à l'inverse du prix.", "c": "marches", "en": "Bond yield"}, "duration": {"t": "Duration", "d": "Mesure de la sensibilité du prix d'une obligation aux variations de taux, liée à sa durée de vie moyenne. Plus elle est longue, plus le prix réagit.", "c": "marches", "en": "Duration"}, "oat-bund": {"t": "OAT et Bund", "d": "OAT : obligations assimilables du Trésor, emprunts de l'État français. Bund : emprunts de l'État allemand, référence de la zone euro. Leur écart de rendement est suivi comme mesure du risque perçu.", "c": "marches", "en": "OAT / Bund"}, "etf": {"t": "ETF (tracker)", "d": "Fonds coté en bourse qui réplique un indice, avec des frais généralement faibles. Il s'achète et se vend comme une action.", "c": "marches", "en": "Exchange Traded Fund"}, "replication-synthetique": {"t": "Réplication physique / synthétique", "d": "Physique : l'ETF détient les titres de l'indice. Synthétique : il détient un autre panier et échange sa performance contre celle de l'indice via un swap avec une banque.", "c": "marches", "en": "Physical / synthetic replication"}, "ter": {"t": "Frais courants (TER)", "d": "Frais annuels d'un fonds, exprimés en pourcentage de l'actif, prélevés automatiquement sur sa valeur.", "c": "marches", "en": "Total Expense Ratio"}, "ecart-de-suivi": {"t": "Écart de suivi", "d": "Différence entre la performance d'un fonds indiciel et celle de son indice, due aux frais, à la fiscalité des dividendes et à la méthode de réplication.", "c": "marches", "en": "Tracking difference / Tracking error"}, "capitalisant-distribuant": {"t": "Capitalisant / distribuant", "d": "Un fonds capitalisant réinvestit les dividendes reçus ; un fonds distribuant les verse aux porteurs.", "c": "marches", "en": "Accumulating / Distributing"}, "etf-levier": {"t": "ETF à levier / inverse", "d": "ETF qui vise un multiple (2×, 3×) ou l'inverse (−1×) de la performance QUOTIDIENNE d'un indice. Sur plusieurs jours, la performance diverge, surtout dans les marchés qui oscillent.", "c": "marches", "en": "Leveraged / Inverse ETF"}, "forex": {"t": "Forex (marché des changes)", "d": "Marché mondial, de gré à gré, où s'échangent les devises, 24 h/24 du dimanche soir au vendredi soir. C'est le plus grand marché financier du monde.", "c": "marches", "en": "Foreign exchange (FX)"}, "paire-de-devises": {"t": "Paire de devises", "d": "Cotation d'une devise (de base) dans une autre (de cotation). Le cours indique combien d'unités de la devise de cotation vaut une unité de la devise de base.", "c": "marches", "en": "Currency pair"}, "devise-de-base": {"t": "Devise de base / de cotation", "d": "Dans une paire, la première devise est la devise de base, la seconde la devise de cotation. Gains et pertes sont exprimés dans la devise de cotation.", "c": "marches", "en": "Base / Quote currency"}, "paires-majeures": {"t": "Paires majeures, croisées, exotiques", "d": "Majeures : grandes devises contre le dollar (EUR/USD, USD/JPY…). Croisées : sans le dollar (EUR/GBP). Exotiques : une devise majeure contre une devise émergente, avec des spreads larges.", "c": "marches", "en": "Majors, crosses, exotics"}, "matieres-premieres": {"t": "Matières premières", "d": "Ressources physiques échangées sur les marchés : énergie, métaux précieux, métaux industriels, produits agricoles. Surtout tradées via des contrats à terme.", "c": "marches", "en": "Commodities"}, "brent-wti": {"t": "Brent et WTI", "d": "Deux qualités de pétrole brut servant de référence mondiale : le Brent (mer du Nord) et le WTI (West Texas Intermediate, États-Unis).", "c": "marches", "en": "Brent / WTI"}, "contango": {"t": "Contango", "d": "Situation où les contrats à terme à échéance lointaine sont plus chers que les proches. Rouler ses positions coûte alors de l'argent.", "c": "marches", "en": "Contango"}, "deport": {"t": "Déport", "d": "Situation inverse du contango : les échéances proches sont plus chères que les lointaines, souvent lors d'une pénurie immédiate.", "c": "marches", "en": "Backwardation"}, "roll": {"t": "Roll (roulement)", "d": "Passage d'un contrat à terme qui arrive à échéance au contrat suivant, pour maintenir une exposition. Peut coûter ou rapporter selon la forme de la courbe.", "c": "marches", "en": "Roll / Rollover"}, "cryptoactif": {"t": "Cryptoactif (cryptomonnaie)", "d": "Actif numérique enregistré sur une blockchain, échangé sur des plateformes 24 h/24. Valeur très volatile et largement fondée sur l'offre et la demande. Encadré en Europe par MiCA.", "c": "marches", "en": "Crypto-asset / Cryptocurrency"}, "blockchain": {"t": "Blockchain", "d": "Registre numérique partagé, sécurisé par cryptographie, où sont enregistrées les transactions d'un cryptoactif.", "c": "marches", "en": "Blockchain"}, "stablecoin": {"t": "Stablecoin", "d": "Cryptoactif conçu pour garder une valeur stable, souvent 1 dollar. Sa stabilité dépend des réserves et du mécanisme de l'émetteur.", "c": "marches", "en": "Stablecoin"}, "cle-privee": {"t": "Clé privée / portefeuille", "d": "Code secret qui permet de disposer de cryptoactifs. Qui détient la clé détient les fonds ; la perdre, c'est perdre les fonds.", "c": "marches", "en": "Private key / Wallet"}, "market-maker": {"t": "Teneur de marché", "d": "Intervenant qui affiche en permanence un prix d'achat et un prix de vente, fournit la liquidité et se rémunère principalement sur le spread.", "c": "marches", "en": "Market maker"}, "hft": {"t": "Trading haute fréquence", "d": "Trading automatisé qui exécute un très grand nombre d'ordres en millisecondes, souvent comme teneur de marché ou arbitragiste.", "c": "marches", "en": "High-Frequency Trading (HFT)"}, "institutionnels": {"t": "Investisseurs institutionnels", "d": "Grands gestionnaires de capitaux : fonds de pension, assureurs, sociétés de gestion, fonds souverains. Ils représentent l'essentiel des volumes.", "c": "marches", "en": "Institutional investors"}, "hedge-fund": {"t": "Hedge fund", "d": "Fonds d'investissement aux stratégies variées (macro, arbitrage, quantitatif…), souvent avec effet de levier et vente à découvert.", "c": "marches", "en": "Hedge fund"}, "liquidite": {"t": "Liquidité", "d": "Facilité à acheter ou vendre rapidement une quantité importante sans faire bouger le prix. Se mesure par le spread, le volume et la profondeur du carnet.", "c": "marches", "en": "Liquidity"}, "volatilite": {"t": "Volatilité", "d": "Ampleur des variations de prix, souvent mesurée par l'écart-type des rendements (annualisé). Ni bonne ni mauvaise : elle crée opportunités et risque.", "c": "marches", "en": "Volatility"}, "sous-jacent": {"t": "Sous-jacent", "d": "Actif dont dépend la valeur d'un produit dérivé (action, indice, devise, matière première…).", "c": "marches", "en": "Underlying"}, "seance": {"t": "Séance et sessions", "d": "Période de cotation d'une bourse. Sur le Forex, on parle de sessions (Asie, Londres, New York), plus ou moins actives.", "c": "marches", "en": "Trading session"}, "fixing": {"t": "Fixing (enchère d'ouverture ou de clôture)", "d": "Phase où les ordres s'accumulent sans être exécutés, puis sont confrontés pour déterminer un prix unique. À Paris, à l'ouverture (9 h) et à la clôture (17 h 30 – 17 h 35).", "c": "marches", "en": "Opening / closing auction"}, "reglement-livraison": {"t": "Règlement-livraison", "d": "Échange effectif des titres contre l'argent après une transaction : J+1 aux États-Unis depuis 2024, J+2 en Europe (passage à J+1 prévu).", "c": "marches", "en": "Settlement"}, "gre-a-gre": {"t": "Gré à gré (OTC)", "d": "Transaction conclue directement entre deux parties, hors d'une bourse organisée. Le Forex au comptant et les CFD sont négociés de gré à gré.", "c": "marches", "en": "Over-the-counter (OTC)"}, "dark-pool": {"t": "Dark pool", "d": "Plateforme de négociation où les ordres ne sont pas affichés publiquement avant exécution, utilisée par les gros intervenants pour limiter leur impact de marché.", "c": "marches", "en": "Dark pool"}, "etc": {"t": "ETC (Exchange Traded Commodity)", "d": "Titre coté qui réplique le prix d'une matière première (or physique, pétrole via des futures…). Juridiquement, c'est souvent un titre de dette de l'émetteur.", "c": "marches", "en": "Exchange Traded Commodity"}, "msci": {"t": "Indices MSCI", "d": "Famille d'indices internationaux calculés par la société MSCI (MSCI World, MSCI Emerging Markets…), très utilisés comme référence par les ETF.", "c": "marches", "en": "MSCI indices"}, "bid": {"t": "Bid (prix acheteur)", "d": "Meilleur prix auquel un intervenant accepte d'acheter. C'est le prix auquel VOUS pouvez vendre immédiatement.", "c": "ordres", "en": "Bid"}, "ask": {"t": "Ask (prix vendeur)", "d": "Meilleur prix auquel un intervenant accepte de vendre. C'est le prix auquel VOUS pouvez acheter immédiatement.", "c": "ordres", "en": "Ask / Offer"}, "spread": {"t": "Spread (écart acheteur-vendeur)", "d": "Écart entre l'ask et le bid. C'est un coût implicite payé à chaque aller-retour, plus large quand la liquidité baisse ou que la volatilité monte.", "c": "ordres", "en": "Bid-ask spread"}, "carnet-d-ordres": {"t": "Carnet d'ordres", "d": "Liste des ordres à cours limité en attente, à l'achat et à la vente, avec prix et quantités.", "c": "ordres", "en": "Order book"}, "profondeur-de-marche": {"t": "Profondeur de marché", "d": "Quantités disponibles à chaque niveau de prix du carnet d'ordres. Elle indique combien on peut échanger sans trop faire bouger le prix.", "c": "ordres", "en": "Market depth (Level 2)"}, "impact-de-marche": {"t": "Impact de marché", "d": "Variation de prix provoquée par l'exécution de son propre ordre, quand il consomme plusieurs niveaux du carnet.", "c": "ordres", "en": "Market impact"}, "ordre-au-marche": {"t": "Ordre au marché", "d": "Ordre exécuté immédiatement au meilleur prix disponible. Exécution quasi certaine sur un marché liquide, prix non garanti.", "c": "ordres", "en": "Market order"}, "ordre-a-cours-limite": {"t": "Ordre à cours limité", "d": "Ordre d'achat à un prix maximal ou de vente à un prix minimal. Prix garanti (ou mieux), exécution non garantie.", "c": "ordres", "en": "Limit order"}, "ordre-stop": {"t": "Ordre stop", "d": "Ordre dormant qui devient un ordre au marché quand le prix atteint un niveau de déclenchement. Sert de stop loss ou d'entrée sur cassure.", "c": "ordres", "en": "Stop order"}, "stop-limite": {"t": "Ordre stop-limite", "d": "Ordre stop qui, une fois déclenché, devient un ordre à cours limité. Prix plafonné, mais risque de non-exécution si le marché saute la limite.", "c": "ordres", "en": "Stop-limit order"}, "trailing-stop": {"t": "Trailing stop (stop suiveur)", "d": "Stop qui suit automatiquement le prix dans le sens favorable à distance fixe, sans jamais reculer. Il protège un gain tout en laissant courir la tendance.", "c": "ordres", "en": "Trailing stop"}, "stop-garanti": {"t": "Stop garanti", "d": "Stop proposé par certains courtiers en CFD, exécuté exactement à son niveau même en cas de gap, moyennant une prime.", "c": "ordres", "en": "Guaranteed stop-loss order (GSLO)"}, "oco": {"t": "OCO (l'un annule l'autre)", "d": "Paire d'ordres liés : l'exécution de l'un annule automatiquement l'autre. Typiquement un objectif et un stop sur la même position.", "c": "ordres", "en": "One-Cancels-the-Other"}, "ordre-lie": {"t": "Ordre lié (bracket)", "d": "Ensemble d'ordres saisis ensemble : une entrée, un stop et un objectif, ces deux derniers liés en OCO.", "c": "ordres", "en": "Bracket order"}, "validite-ordre": {"t": "Durée de validité d'un ordre", "d": "Durée pendant laquelle un ordre reste actif : jour, à révocation (GTC), à date (GTD), exécuter ou annuler (IOC), tout ou rien (FOK).", "c": "ordres", "en": "Time in force (Day, GTC, GTD, IOC, FOK)"}, "priorite-prix-temps": {"t": "Priorité prix-temps", "d": "Règle d'exécution des ordres limités en bourse : d'abord le meilleur prix, puis, à prix égal, l'ordre arrivé en premier.", "c": "ordres", "en": "Price-time priority"}, "ordre-iceberg": {"t": "Ordre iceberg", "d": "Ordre de grande taille dont seule une petite partie est visible dans le carnet ; la suite apparaît au fur et à mesure.", "c": "ordres", "en": "Iceberg order"}, "slippage": {"t": "Slippage (glissement)", "d": "Différence entre le prix attendu et le prix réellement obtenu, fréquente sur les stops, lors des annonces et sur les titres peu liquides.", "c": "ordres", "en": "Slippage"}, "gap": {"t": "Gap", "d": "Écart entre deux cotations successives sans échange intermédiaire, souvent entre la clôture et l'ouverture suivante. Un stop situé dans le gap est exécuté bien au-delà de son niveau.", "c": "ordres", "en": "Gap"}, "position-longue": {"t": "Position longue", "d": "Position qui gagne quand le prix monte : on achète d'abord, on vend ensuite. Perte maximale : la mise (pour un achat sans levier).", "c": "ordres", "en": "Long position"}, "position-courte": {"t": "Position courte", "d": "Position qui gagne quand le prix baisse : on vend d'abord, on rachète ensuite. Perte théoriquement illimitée.", "c": "ordres", "en": "Short position"}, "vente-a-decouvert": {"t": "Vente à découvert", "d": "Vente d'un actif que l'on ne possède pas (emprunté), dans le but de le racheter moins cher. Implique des frais d'emprunt et le reversement des dividendes.", "c": "ordres", "en": "Short selling"}, "frais-d-emprunt": {"t": "Frais d'emprunt de titres", "d": "Coût payé pour emprunter les titres vendus à découvert, plus élevé pour les titres difficiles à emprunter.", "c": "ordres", "en": "Borrow fee"}, "short-squeeze": {"t": "Short squeeze", "d": "Hausse brutale provoquée par les rachats forcés ou précipités de nombreux vendeurs à découvert, qui alimentent eux-mêmes la hausse.", "c": "ordres", "en": "Short squeeze"}, "execution-partielle": {"t": "Exécution partielle", "d": "Exécution d'une partie seulement d'un ordre, faute de contrepartie suffisante au prix demandé.", "c": "ordres", "en": "Partial fill"}, "avis-d-opere": {"t": "Avis d'opéré", "d": "Document émis par le courtier après chaque transaction : date, quantité, prix, frais. Justificatif utile pour la fiscalité.", "c": "ordres", "en": "Trade confirmation"}, "srd": {"t": "SRD (service de règlement différé)", "d": "Service proposé sur les valeurs françaises les plus liquides, permettant de différer le règlement à la fin du mois et d'utiliser un effet de levier, y compris pour vendre à découvert.", "c": "ordres", "en": "Deferred settlement service"}, "comptant": {"t": "Comptant", "d": "Achat ou vente de l'actif lui-même, payé en totalité et livré (après le délai de règlement). S'oppose aux produits dérivés.", "c": "produits", "en": "Spot / Cash market"}, "produit-derive": {"t": "Produit dérivé", "d": "Contrat dont la valeur dépend du prix d'un autre actif, le sous-jacent. Il permet de se couvrir ou de spéculer, souvent avec effet de levier.", "c": "produits", "en": "Derivative"}, "cfd": {"t": "CFD (contrat sur différence)", "d": "Contrat de gré à gré avec un courtier, par lequel on échange la différence de prix d'un actif entre ouverture et clôture, sans le posséder, avec une marge. Encadré en Europe pour les particuliers (leviers plafonnés, protection contre le solde négatif).", "c": "produits", "en": "Contract for Difference"}, "contrat-a-terme": {"t": "Contrat à terme (future)", "d": "Engagement standardisé, négocié en bourse, d'acheter ou de vendre un actif à un prix fixé aujourd'hui pour une date future. Garanti par une chambre de compensation, avec appels de marge quotidiens.", "c": "produits", "en": "Futures contract"}, "forward": {"t": "Contrat à terme de gré à gré (forward)", "d": "Contrat à terme non standardisé, conclu directement entre deux parties, souvent utilisé par les entreprises pour se couvrir.", "c": "produits", "en": "Forward contract"}, "chambre-de-compensation": {"t": "Chambre de compensation", "d": "Organisme qui s'interpose entre acheteurs et vendeurs de contrats en bourse et garantit leur bonne exécution, en exigeant des dépôts de garantie.", "c": "produits", "en": "Clearing house"}, "depot-de-garantie": {"t": "Dépôt de garantie", "d": "Somme exigée pour ouvrir une position sur un contrat à terme, fixée par la chambre de compensation selon la volatilité.", "c": "produits", "en": "Initial margin"}, "mark-to-market": {"t": "Évaluation quotidienne (mark-to-market)", "d": "Réévaluation quotidienne des positions au prix du marché, avec crédit ou débit immédiat des gains et pertes.", "c": "produits", "en": "Mark-to-market"}, "multiplicateur": {"t": "Multiplicateur (valeur du point)", "d": "Montant gagné ou perdu pour une variation d'un point du prix d'un contrat.", "c": "produits", "en": "Contract multiplier / Point value"}, "taille-de-contrat": {"t": "Taille de contrat", "d": "Quantité de sous-jacent représentée par un contrat (nombre d'actions pour une option, unités de devise pour un lot, valeur du point pour un future).", "c": "produits", "en": "Contract size"}, "micro-contrat": {"t": "Micro-contrat", "d": "Version réduite d'un contrat à terme (souvent 1/10 du contrat « mini »), adaptée aux petits comptes.", "c": "produits", "en": "Micro contract"}, "echeance": {"t": "Échéance", "d": "Date à laquelle un contrat à terme ou une option expire, ou à laquelle une obligation est remboursée.", "c": "produits", "en": "Expiry / Maturity"}, "livraison-physique": {"t": "Livraison physique / règlement en espèces", "d": "À l'échéance, certains contrats se dénouent par la livraison de la marchandise, d'autres par le paiement de la différence en argent.", "c": "produits", "en": "Physical delivery / Cash settlement"}, "option": {"t": "Option", "d": "Contrat donnant à son acheteur le droit, mais pas l'obligation, d'acheter (call) ou de vendre (put) un actif à un prix fixé (strike) jusqu'à une date donnée, contre une prime.", "c": "produits", "en": "Option"}, "call": {"t": "Call (option d'achat)", "d": "Option donnant le droit d'acheter le sous-jacent au prix d'exercice. Son acheteur gagne si le prix monte au-delà de strike + prime.", "c": "produits", "en": "Call option"}, "put": {"t": "Put (option de vente)", "d": "Option donnant le droit de vendre le sous-jacent au prix d'exercice. Son acheteur gagne si le prix baisse sous strike − prime ; sert aussi d'assurance.", "c": "produits", "en": "Put option"}, "prime": {"t": "Prime (d'une option)", "d": "Prix payé par l'acheteur d'une option au vendeur. C'est la perte maximale de l'acheteur et le gain maximal du vendeur.", "c": "produits", "en": "Premium"}, "strike": {"t": "Prix d'exercice (strike)", "d": "Prix auquel l'acheteur d'une option peut acheter (call) ou vendre (put) le sous-jacent.", "c": "produits", "en": "Strike price"}, "option-europeenne-americaine": {"t": "Option européenne / américaine", "d": "Une option européenne ne s'exerce qu'à l'échéance ; une option américaine à tout moment jusqu'à l'échéance. Les noms ne désignent pas des lieux.", "c": "produits", "en": "European / American option"}, "valeur-intrinseque": {"t": "Valeur intrinsèque", "d": "Ce que rapporterait une option si on l'exerçait immédiatement : max(S − K ; 0) pour un call, max(K − S ; 0) pour un put.", "c": "produits", "en": "Intrinsic value"}, "valeur-temps": {"t": "Valeur temps", "d": "Part de la prime d'une option au-delà de sa valeur intrinsèque ; elle diminue avec le temps (thêta) et s'annule à l'échéance.", "c": "produits", "en": "Time value / Extrinsic value"}, "dans-la-monnaie": {"t": "Dans / à / hors de la monnaie", "d": "Une option est dans la monnaie si elle a une valeur intrinsèque, à la monnaie si le prix du sous-jacent est proche du strike, hors de la monnaie sinon.", "c": "produits", "en": "In / At / Out of the money (ITM, ATM, OTM)"}, "grecques": {"t": "Grecques", "d": "Mesures de sensibilité de la prime d'une option : delta (prix du sous-jacent), gamma (variation du delta), thêta (temps), vega (volatilité implicite), rhô (taux).", "c": "produits", "en": "Greeks"}, "delta": {"t": "Delta", "d": "Variation approximative de la prime d'une option pour 1 unité de variation du sous-jacent ; entre 0 et 1 pour un call, entre −1 et 0 pour un put.", "c": "produits", "en": "Delta"}, "gamma": {"t": "Gamma", "d": "Vitesse de variation du delta quand le sous-jacent bouge ; élevé pour les options à la monnaie proches de l'échéance.", "c": "produits", "en": "Gamma"}, "theta": {"t": "Thêta", "d": "Perte de valeur d'une option par jour qui passe, toutes choses égales par ailleurs. Négatif pour l'acheteur, l'érosion s'accélère près de l'échéance.", "c": "produits", "en": "Theta"}, "vega": {"t": "Vega", "d": "Variation de la prime d'une option pour un point de volatilité implicite.", "c": "produits", "en": "Vega"}, "black-scholes": {"t": "Modèle de Black-Scholes", "d": "Modèle mathématique de valorisation des options (1973), fondé sur des hypothèses simplificatrices (volatilité constante, rendements log-normaux). Base du calcul des grecques.", "c": "produits", "en": "Black-Scholes model"}, "warrant": {"t": "Warrant", "d": "Produit coté émis par une banque, qui fonctionne comme une option (call ou put) avec une échéance, une prime et une sensibilité au temps et à la volatilité.", "c": "produits", "en": "Warrant"}, "turbo": {"t": "Turbo", "d": "Produit coté à effet de levier, émis par une banque, avec une barrière désactivante : si le sous-jacent la touche, le turbo est désactivé (perte totale ou presque).", "c": "produits", "en": "Turbo / Knock-out certificate"}, "barriere-desactivante": {"t": "Barrière désactivante", "d": "Niveau de prix qui, s'il est touché, met fin au produit (turbo). La désactivation est définitive, même si le prix revient ensuite.", "c": "produits", "en": "Knock-out barrier"}, "parite": {"t": "Parité", "d": "Nombre de warrants ou de turbos nécessaires pour représenter une unité de sous-jacent.", "c": "produits", "en": "Ratio / Parity"}, "effet-de-levier": {"t": "Effet de levier", "d": "Rapport entre l'exposition et le capital engagé. Il multiplie gains et pertes : avec un levier de 10, un mouvement de 1 % fait varier le capital de 10 %.", "c": "produits", "en": "Leverage"}, "levier-effectif": {"t": "Levier effectif", "d": "Exposition totale réellement prise divisée par le capital du compte, à distinguer du levier maximal autorisé par le courtier.", "c": "produits", "en": "Effective leverage"}, "marge": {"t": "Marge", "d": "Somme bloquée par le courtier en garantie d'une position à effet de levier. Marge = exposition ÷ levier maximal.", "c": "produits", "en": "Margin"}, "appel-de-marge": {"t": "Appel de marge", "d": "Demande du courtier de remettre des fonds ou de réduire ses positions quand les pertes font tomber le compte sous le niveau de marge requis.", "c": "produits", "en": "Margin call"}, "liquidation": {"t": "Liquidation (clôture forcée)", "d": "Fermeture automatique des positions par le courtier quand le niveau de marge atteint un seuil (50 % pour les CFD des particuliers en Europe), au prix du marché.", "c": "produits", "en": "Liquidation / Margin close-out"}, "pip": {"t": "Pip", "d": "Unité standard de variation sur le Forex : 0,0001 pour la plupart des paires, 0,01 pour les paires en yen.", "c": "produits", "en": "Pip (percentage in point)"}, "pipette": {"t": "Pipette", "d": "Dixième de pip, correspondant à la décimale supplémentaire affichée par beaucoup de plateformes.", "c": "produits", "en": "Pipette / Fractional pip"}, "valeur-du-pip": {"t": "Valeur du pip", "d": "Gain ou perte pour une variation d'un pip, selon la taille de la position, exprimé d'abord dans la devise de cotation.", "c": "produits", "en": "Pip value"}, "lot": {"t": "Lot", "d": "Unité de taille des positions sur le Forex : lot standard = 100 000 unités de la devise de base ; mini-lot = 10 000 ; micro-lot = 1 000.", "c": "produits", "en": "Lot"}, "tick": {"t": "Tick", "d": "Plus petite variation de prix possible d'un instrument ; sa valeur monétaire = taille du tick × multiplicateur.", "c": "produits", "en": "Tick"}, "notionnel": {"t": "Notionnel (valeur de la position)", "d": "Valeur totale de l'exposition d'une position à effet de levier, sur laquelle se calculent les gains, les pertes et souvent les frais de financement.", "c": "produits", "en": "Notional value"}, "exposition": {"t": "Exposition", "d": "Montant total soumis aux variations de prix sur une position ou un compte. C'est elle, rapportée au capital, qui mesure le risque.", "c": "produits", "en": "Exposure"}, "financement-overnight": {"t": "Financement overnight", "d": "Intérêt facturé (ou parfois versé) chaque nuit sur une position à effet de levier conservée, calculé sur le notionnel.", "c": "produits", "en": "Overnight financing"}, "swap": {"t": "Swap", "d": "1) Sur le Forex et les CFD : frais (ou crédit) de financement d'une position gardée la nuit, lié à l'écart de taux ; souvent triplé le mercredi. 2) Plus largement : contrat d'échange de flux entre deux parties (utilisé par les ETF synthétiques).", "c": "produits", "en": "Swap / Rollover"}, "commission": {"t": "Commission", "d": "Frais facturés par le courtier pour exécuter un ordre : montant fixe, pourcentage du montant ou montant par contrat.", "c": "produits", "en": "Commission"}, "frais-de-transaction": {"t": "Frais de transaction (coût total)", "d": "Ensemble des coûts d'un trade : commission, spread, slippage, financement, change et autres frais. Ils pèsent d'autant plus que l'horizon est court.", "c": "produits", "en": "Transaction costs"}, "perpetuel": {"t": "Contrat perpétuel", "d": "Dérivé sans échéance, courant sur les plateformes de cryptoactifs, dont le prix est rapproché du comptant par des paiements périodiques (« funding »). Souvent proposé avec des leviers extrêmes hors UE.", "c": "produits", "en": "Perpetual futures"}, "analyse-technique": {"t": "Analyse technique", "d": "Étude de l'historique des prix et des volumes pour formuler des hypothèses de trading et structurer les décisions (entrées, stops, objectifs). Son pouvoir prédictif est débattu.", "c": "technique", "en": "Technical analysis"}, "theorie-de-dow": {"t": "Théorie de Dow", "d": "Ensemble de principes issus des écrits de Charles Dow (fin du XIXe siècle) : le prix intègre l'information, les marchés évoluent en tendances, les volumes confirment.", "c": "technique", "en": "Dow theory"}, "efficience-des-marches": {"t": "Efficience des marchés", "d": "Hypothèse (Eugene Fama) selon laquelle les prix reflètent l'information disponible, de sorte qu'il est très difficile de battre durablement le marché après frais.", "c": "technique", "en": "Efficient market hypothesis"}, "chandelier": {"t": "Chandelier japonais (bougie)", "d": "Représentation d'une période de prix avec un corps (de l'ouverture à la clôture) et des mèches (jusqu'aux extrêmes). Vert/blanc si la clôture dépasse l'ouverture, rouge/noir sinon.", "c": "technique", "en": "Candlestick"}, "ohlc": {"t": "OHLC", "d": "Les quatre prix qui résument une période : ouverture (Open), plus haut (High), plus bas (Low), clôture (Close).", "c": "technique", "en": "Open, High, Low, Close"}, "graphique-en-barres": {"t": "Graphique en barres / en ligne", "d": "Graphique en barres : trait vertical du plus bas au plus haut, tirets pour l'ouverture et la clôture. Graphique en ligne : relie les seules clôtures.", "c": "technique", "en": "Bar chart / Line chart"}, "meche": {"t": "Mèche", "d": "Partie fine d'une bougie, entre le corps et le plus haut (mèche haute) ou le plus bas (mèche basse). Elle montre les prix rejetés pendant la période.", "c": "technique", "en": "Wick / Shadow"}, "unite-de-temps": {"t": "Unité de temps", "d": "Durée représentée par chaque bougie : 1 minute (M1), 1 heure (H1), 1 jour (D1), 1 semaine (W1)… Chaque unité a sa propre tendance.", "c": "technique", "en": "Timeframe"}, "tendance": {"t": "Tendance", "d": "Direction dominante des prix : haussière (sommets et creux de plus en plus hauts), baissière (de plus en plus bas), ou absente (range).", "c": "technique", "en": "Trend"}, "structure-de-marche": {"t": "Structure de marché", "d": "Succession des sommets et creux qui définit la tendance. Une rupture de structure survient quand le prix casse le dernier creux (ou sommet) significatif.", "c": "technique", "en": "Market structure"}, "range": {"t": "Range (marché latéral)", "d": "Marché sans tendance, qui oscille entre un support et une résistance.", "c": "technique", "en": "Range / Sideways market"}, "support": {"t": "Support", "d": "Zone de prix où la baisse s'est arrêtée plusieurs fois, car des acheteurs y apparaissent. C'est une zone, pas une ligne précise.", "c": "technique", "en": "Support"}, "resistance": {"t": "Résistance", "d": "Zone de prix où la hausse s'est arrêtée plusieurs fois, car des vendeurs y apparaissent.", "c": "technique", "en": "Resistance"}, "inversion-des-roles": {"t": "Inversion des rôles", "d": "Principe selon lequel une résistance cassée devient souvent un support, et un support cassé une résistance.", "c": "technique", "en": "Role reversal (polarity)"}, "cassure": {"t": "Cassure (breakout)", "d": "Franchissement d'un niveau important (résistance, support, ligne de tendance, figure). Peut être fausse si le prix revient rapidement.", "c": "technique", "en": "Breakout"}, "fausse-cassure": {"t": "Fausse cassure", "d": "Cassure suivie d'un retour rapide dans la zone précédente, qui piège ceux qui ont agi sur la cassure.", "c": "technique", "en": "False breakout / Fakeout"}, "ligne-de-tendance": {"t": "Ligne de tendance", "d": "Droite reliant au moins deux creux (tendance haussière) ou deux sommets (baissière), validée au troisième contact.", "c": "technique", "en": "Trendline"}, "canal": {"t": "Canal", "d": "Couloir formé par une ligne de tendance et une parallèle passant par les extrêmes opposés.", "c": "technique", "en": "Channel"}, "echelle-logarithmique": {"t": "Échelle logarithmique", "d": "Échelle de prix où un même écart vertical représente un même pourcentage. Plus pertinente pour les longues périodes ou les fortes hausses.", "c": "technique", "en": "Log scale"}, "volume": {"t": "Volume", "d": "Quantité échangée sur une période (titres ou contrats). Mesure l'intensité de la participation ; sur le Forex au comptant, seul un volume de ticks est disponible.", "c": "technique", "en": "Volume"}, "volume-de-ticks": {"t": "Volume de ticks", "d": "Nombre de variations de prix sur une période, utilisé comme indicateur indirect d'activité quand le volume réel n'est pas disponible (Forex).", "c": "technique", "en": "Tick volume"}, "pullback": {"t": "Pullback (repli)", "d": "Retour temporaire du prix contre la tendance, avant reprise. Aussi : retour sur un niveau cassé.", "c": "technique", "en": "Pullback"}, "swing": {"t": "Swing (sommet et creux)", "d": "Point haut ou bas marquant un retournement local des prix ; la suite des swings définit la structure de marché.", "c": "technique", "en": "Swing high / Swing low"}, "doji": {"t": "Doji", "d": "Bougie dont l'ouverture et la clôture sont presque égales : indécision.", "c": "technique", "en": "Doji"}, "marteau": {"t": "Marteau / pendu", "d": "Bougie à petit corps en haut et longue mèche basse (au moins 2 fois le corps). Marteau après une baisse, pendu après une hausse.", "c": "technique", "en": "Hammer / Hanging man"}, "etoile-filante": {"t": "Étoile filante / marteau inversé", "d": "Bougie à petit corps en bas et longue mèche haute. Étoile filante après une hausse (rejet des prix élevés), marteau inversé après une baisse.", "c": "technique", "en": "Shooting star / Inverted hammer"}, "toupie": {"t": "Toupie et marubozu", "d": "Toupie : petit corps, mèches des deux côtés (indécision). Marubozu : grand corps sans mèches (domination nette d'un camp).", "c": "technique", "en": "Spinning top / Marubozu"}, "avalement": {"t": "Avalement", "d": "Configuration de deux bougies où le corps de la seconde englobe entièrement celui de la première, en sens inverse. Haussier après une baisse, baissier après une hausse.", "c": "technique", "en": "Engulfing pattern"}, "harami": {"t": "Harami", "d": "Configuration où une petite bougie a son corps contenu dans celui de la grande bougie précédente : essoufflement.", "c": "technique", "en": "Harami"}, "etoile-du-matin": {"t": "Étoile du matin / du soir", "d": "Configuration de retournement à trois bougies : grande bougie dans le sens de la tendance, petite bougie, puis grande bougie inverse qui pénètre la première.", "c": "technique", "en": "Morning star / Evening star"}, "trois-soldats": {"t": "Trois soldats blancs / trois corbeaux", "d": "Trois grandes bougies successives dans le même sens, aux clôtures de plus en plus hautes (soldats) ou basses (corbeaux).", "c": "technique", "en": "Three white soldiers / Three black crows"}, "figure-chartiste": {"t": "Figure chartiste", "d": "Forme dessinée par les prix sur de nombreuses bougies, classée comme figure de retournement ou de continuation. Sa fiabilité est débattue et sa lecture subjective.", "c": "technique", "en": "Chart pattern"}, "tete-epaules": {"t": "Tête-épaules", "d": "Figure de retournement à trois sommets, celui du milieu plus haut ; signal à la cassure de la ligne de cou. La version inversée signale un retournement haussier.", "c": "technique", "en": "Head and shoulders"}, "ligne-de-cou": {"t": "Ligne de cou", "d": "Ligne reliant les creux (ou les sommets) d'une tête-épaules ou d'un double sommet ; sa cassure complète la figure.", "c": "technique", "en": "Neckline"}, "double-sommet": {"t": "Double sommet / double creux", "d": "Figure de retournement formée de deux sommets (ou creux) à peu près au même niveau, confirmée par la cassure du creux (ou sommet) intermédiaire.", "c": "technique", "en": "Double top / Double bottom"}, "triangle": {"t": "Triangle", "d": "Figure de consolidation à lignes convergentes : symétrique, ascendant (résistance plate, creux montants) ou descendant (support plat, sommets descendants).", "c": "technique", "en": "Triangle"}, "drapeau": {"t": "Drapeau / fanion", "d": "Figure de continuation : après un mouvement rapide (le mât), courte consolidation en petit canal (drapeau) ou petit triangle (fanion), puis reprise.", "c": "technique", "en": "Flag / Pennant"}, "biseau": {"t": "Biseau", "d": "Figure à deux lignes convergentes inclinées dans le même sens. Le biseau ascendant est souvent considéré comme baissier, le descendant comme haussier.", "c": "technique", "en": "Wedge"}, "rectangle": {"t": "Rectangle", "d": "Figure de consolidation entre un support et une résistance horizontaux ; objectif théorique égal à sa hauteur.", "c": "technique", "en": "Rectangle"}, "indicateur-technique": {"t": "Indicateur technique", "d": "Calcul appliqué aux prix et parfois aux volumes pour en extraire une information (tendance, élan, volatilité). Tous sont dérivés du prix et retardés.", "c": "technique", "en": "Technical indicator"}, "oscillateur": {"t": "Oscillateur", "d": "Indicateur qui évolue entre des bornes ou autour d'une valeur centrale, mesurant l'élan ou la position du prix dans son amplitude récente.", "c": "technique", "en": "Oscillator"}, "momentum": {"t": "Momentum (élan)", "d": "Vitesse ou force d'un mouvement de prix. En recherche financière, l'effet momentum désigne la tendance des actifs ayant le plus monté à continuer de surperformer sur quelques mois.", "c": "technique", "en": "Momentum"}, "moyenne-mobile": {"t": "Moyenne mobile", "d": "Moyenne des derniers prix qui « glisse » à chaque période. Simple (SMA) ou exponentielle (EMA, plus réactive). Sert surtout à filtrer le contexte.", "c": "technique", "en": "Moving average"}, "sma": {"t": "SMA (moyenne mobile simple)", "d": "Moyenne arithmétique des N dernières clôtures. En tendance régulière, elle est en retard d'environ (N − 1) ÷ 2 périodes.", "c": "technique", "en": "Simple Moving Average"}, "ema": {"t": "EMA (moyenne mobile exponentielle)", "d": "Moyenne qui donne plus de poids aux prix récents : EMA = prix × k + EMA précédente × (1 − k), avec k = 2 ÷ (N + 1).", "c": "technique", "en": "Exponential Moving Average"}, "croisement-de-moyennes": {"t": "Croisement de moyennes (golden cross, death cross)", "d": "Passage d'une moyenne mobile courte au-dessus (haussier) ou en dessous (baissier) d'une moyenne longue. Signal tardif, nombreux faux signaux en range.", "c": "technique", "en": "Moving average crossover"}, "macd": {"t": "MACD", "d": "Indicateur de tendance et d'élan : ligne MACD = EMA 12 − EMA 26 ; ligne de signal = EMA 9 du MACD ; histogramme = différence entre les deux.", "c": "technique", "en": "Moving Average Convergence Divergence"}, "rsi": {"t": "RSI", "d": "Oscillateur de Wilder (0 à 100) comparant les hausses et les baisses moyennes : RSI = 100 − 100 ÷ (1 + RS). Zones usuelles 70 (surachat) et 30 (survente).", "c": "technique", "en": "Relative Strength Index"}, "surachat-survente": {"t": "Surachat / survente", "d": "Zones extrêmes d'un oscillateur (par exemple RSI au-dessus de 70 ou sous 30). Ce ne sont pas des signaux de retournement : en tendance, elles peuvent durer.", "c": "technique", "en": "Overbought / Oversold"}, "stochastique": {"t": "Stochastique", "d": "Oscillateur de George Lane situant la clôture dans l'amplitude des N dernières périodes : %K = (C − bas) ÷ (haut − bas) × 100 ; %D = moyenne de %K.", "c": "technique", "en": "Stochastic oscillator"}, "bandes-de-bollinger": {"t": "Bandes de Bollinger", "d": "Enveloppe autour d'une moyenne mobile 20, à ± 2 écarts-types. S'écarte quand la volatilité monte, se resserre (squeeze) quand elle baisse.", "c": "technique", "en": "Bollinger Bands"}, "squeeze": {"t": "Squeeze (compression)", "d": "Resserrement marqué des bandes de Bollinger, signe d'une volatilité anormalement faible, souvent suivie d'un mouvement plus ample dont le sens est inconnu.", "c": "technique", "en": "Squeeze"}, "atr": {"t": "ATR (Average True Range)", "d": "Moyenne du « true range » sur N périodes (14 par défaut) : mesure de volatilité en unités de prix, utilisée pour placer les stops et dimensionner les positions.", "c": "technique", "en": "Average True Range"}, "true-range": {"t": "True Range", "d": "Amplitude d'une bougie intégrant les gaps : max(haut − bas ; |haut − clôture précédente| ; |bas − clôture précédente|).", "c": "technique", "en": "True Range"}, "vwap": {"t": "VWAP", "d": "Prix moyen pondéré par les volumes depuis le début de la séance. Référence d'exécution des institutionnels et repère intraday.", "c": "technique", "en": "Volume Weighted Average Price"}, "ichimoku": {"t": "Ichimoku", "d": "Système d'indicateurs (Tenkan, Kijun, nuage formé par Senkou A et B projetées 26 périodes en avant, Chikou) résumant tendance, élan et zones de support et résistance.", "c": "technique", "en": "Ichimoku Kinko Hyo"}, "fibonacci": {"t": "Retracements de Fibonacci", "d": "Niveaux de repli possibles d'un mouvement : 23,6 ; 38,2 ; 50 ; 61,8 et 78,6 %. Fondement théorique faible ; utiles surtout comme zones surveillées par beaucoup d'intervenants.", "c": "technique", "en": "Fibonacci retracements"}, "divergence": {"t": "Divergence", "d": "Désaccord entre le prix et un oscillateur : nouveau sommet du prix sans nouveau sommet de l'oscillateur (divergence baissière), ou l'inverse. Signale un essoufflement, pas un retournement.", "c": "technique", "en": "Divergence"}, "ecart-type": {"t": "Écart-type", "d": "Mesure statistique de la dispersion des valeurs autour de leur moyenne. Appliqué aux rendements, il mesure la volatilité.", "c": "technique", "en": "Standard deviation"}, "surcharge-indicateurs": {"t": "Surcharge d'indicateurs", "d": "Accumulation d'indicateurs redondants sur un graphique, qui donne une fausse impression de confirmation et favorise le surapprentissage.", "c": "technique", "en": "Indicator overload"}, "obv": {"t": "OBV (On-Balance Volume)", "d": "Indicateur de volume cumulé : on ajoute le volume des séances haussières et on retranche celui des séances baissières. Sert à vérifier si le volume accompagne la tendance.", "c": "technique", "en": "On-Balance Volume"}, "cci-williams": {"t": "CCI et Williams %R", "d": "Deux oscillateurs d'élan proches du RSI et du stochastique ; les utiliser ensemble crée de la redondance.", "c": "technique", "en": "Commodity Channel Index / Williams %R"}, "apophenie": {"t": "Apophénie", "d": "Tendance du cerveau à percevoir des motifs ou des liens dans des données aléatoires.", "c": "technique", "en": "Apophenia"}, "analyse-fondamentale": {"t": "Analyse fondamentale", "d": "Étude des facteurs qui déterminent la valeur d'un actif : situation économique, politique monétaire, résultats et valorisation des entreprises.", "c": "fondamentale", "en": "Fundamental analysis"}, "pib": {"t": "PIB (produit intérieur brut)", "d": "Valeur de la production d'un pays sur une période. Sa croissance mesure l'activité. Publié chaque trimestre (annualisé aux États-Unis, trimestriel brut en zone euro).", "c": "fondamentale", "en": "GDP (Gross Domestic Product)"}, "inflation": {"t": "Inflation", "d": "Hausse générale et durable des prix, mesurée notamment par l'indice des prix à la consommation. Les banques centrales visent en général environ 2 % à moyen terme.", "c": "fondamentale", "en": "Inflation"}, "ipc": {"t": "IPC et inflation sous-jacente", "d": "Indice des prix à la consommation (IPCH harmonisé en zone euro, CPI aux États-Unis). L'inflation sous-jacente exclut les éléments volatils comme l'énergie et l'alimentation.", "c": "fondamentale", "en": "CPI (Consumer Price Index) / Core inflation"}, "nfp": {"t": "Rapport sur l'emploi (NFP)", "d": "Publication mensuelle américaine des créations d'emplois hors secteur agricole, avec le taux de chômage et les salaires. Très suivie, elle provoque souvent de forts mouvements.", "c": "fondamentale", "en": "Non-Farm Payrolls"}, "taux-de-chomage": {"t": "Taux de chômage", "d": "Part de la population active sans emploi et en recherche d'emploi. Indicateur clé du mandat de la Fed.", "c": "fondamentale", "en": "Unemployment rate"}, "pmi": {"t": "PMI (indice des directeurs d'achat)", "d": "Enquête mensuelle auprès des entreprises. Au-dessus de 50 : activité en expansion ; en dessous : en contraction. Publiée tôt, elle anticipe souvent les statistiques officielles.", "c": "fondamentale", "en": "Purchasing Managers' Index"}, "banque-centrale": {"t": "Banque centrale", "d": "Institution qui conduit la politique monétaire (taux directeurs, bilan) et veille à la stabilité des prix et du système financier.", "c": "fondamentale", "en": "Central bank"}, "bce": {"t": "BCE (Banque centrale européenne)", "d": "Banque centrale de la zone euro, à Francfort, dont le mandat principal est la stabilité des prix (objectif de 2 % à moyen terme). Elle décide de sa politique monétaire environ toutes les six semaines.", "c": "fondamentale", "en": "ECB (European Central Bank)"}, "fed": {"t": "Fed (Réserve fédérale)", "d": "Banque centrale des États-Unis, au double mandat : stabilité des prix et plein emploi. Son comité, le FOMC, se réunit 8 fois par an et fixe la fourchette cible des fonds fédéraux.", "c": "fondamentale", "en": "Federal Reserve"}, "taux-directeur": {"t": "Taux directeur", "d": "Taux d'intérêt de court terme fixé par une banque centrale, qui influence l'ensemble des taux de l'économie.", "c": "fondamentale", "en": "Policy rate / Key interest rate"}, "taux-reel": {"t": "Taux réel", "d": "Taux nominal diminué de l'inflation : il mesure le vrai coût de l'argent.", "c": "fondamentale", "en": "Real interest rate"}, "hawkish-dovish": {"t": "Hawkish / dovish", "d": "Qualifie le ton d'une banque centrale : hawkish (« faucon »), priorité à la lutte contre l'inflation, taux plus hauts ; dovish (« colombe »), priorité au soutien de l'activité.", "c": "fondamentale", "en": "Hawkish / Dovish"}, "qe": {"t": "Assouplissement quantitatif (QE)", "d": "Achats massifs de titres (surtout obligations) par une banque centrale pour faire baisser les taux longs ; le resserrement quantitatif (QT) est l'opération inverse.", "c": "fondamentale", "en": "Quantitative easing / tightening (QE / QT)"}, "forward-guidance": {"t": "Forward guidance", "d": "Communication d'une banque centrale sur l'orientation future de sa politique, pour guider les anticipations des marchés.", "c": "fondamentale", "en": "Forward guidance"}, "carry-trade": {"t": "Carry trade", "d": "Stratégie consistant à emprunter dans une devise à taux bas pour placer dans une devise à taux élevé. Rentable tant que le change reste stable, elle peut se retourner brutalement.", "c": "fondamentale", "en": "Carry trade"}, "calendrier-economique": {"t": "Calendrier économique", "d": "Liste des publications économiques et événements à venir, avec heure, importance, chiffre précédent, consensus et chiffre réel.", "c": "fondamentale", "en": "Economic calendar"}, "consensus": {"t": "Consensus", "d": "Prévision moyenne des économistes ou des analystes pour une statistique ou un résultat d'entreprise. Les marchés réagissent à l'écart avec le consensus.", "c": "fondamentale", "en": "Consensus / Forecast"}, "surprise-economique": {"t": "Surprise (économique)", "d": "Écart entre le chiffre publié et le consensus. C'est elle, plus que le chiffre lui-même, qui fait bouger les prix.", "c": "fondamentale", "en": "Surprise"}, "revision": {"t": "Révision", "d": "Correction d'une statistique déjà publiée lors d'une publication ultérieure. Elle peut modifier fortement l'interprétation d'un nouveau chiffre.", "c": "fondamentale", "en": "Revision"}, "resultats-entreprise": {"t": "Résultats d'entreprise", "d": "Comptes publiés périodiquement par une société cotée : chiffre d'affaires, marges, résultat net, BPA, perspectives. Publiés souvent hors séance, ils provoquent des gaps.", "c": "fondamentale", "en": "Earnings"}, "chiffre-d-affaires": {"t": "Chiffre d'affaires", "d": "Total des ventes d'une entreprise sur une période.", "c": "fondamentale", "en": "Revenue / Sales"}, "marge-operationnelle": {"t": "Marge opérationnelle / marge nette", "d": "Part du chiffre d'affaires qui reste en bénéfice, avant (opérationnelle) ou après (nette) frais financiers et impôts.", "c": "fondamentale", "en": "Operating margin / Net margin"}, "resultat-net": {"t": "Résultat net", "d": "Bénéfice (ou perte) final d'une entreprise après toutes les charges et les impôts.", "c": "fondamentale", "en": "Net income"}, "bpa": {"t": "BPA (bénéfice par action)", "d": "Résultat net divisé par le nombre d'actions.", "c": "fondamentale", "en": "EPS (Earnings Per Share)"}, "guidance": {"t": "Guidance (perspectives)", "d": "Prévisions communiquées par la direction d'une entreprise pour les périodes à venir. Elle pèse souvent plus que les résultats passés.", "c": "fondamentale", "en": "Guidance / Outlook"}, "beat-miss": {"t": "Beat / miss", "d": "Jargon : un résultat « beat » dépasse le consensus, un « miss » est inférieur.", "c": "fondamentale", "en": "Beat / Miss"}, "capitalisation-boursiere": {"t": "Capitalisation boursière", "d": "Valeur en bourse d'une société : cours × nombre d'actions.", "c": "fondamentale", "en": "Market capitalization"}, "per": {"t": "PER (Price Earnings Ratio)", "d": "Cours divisé par le BPA : nombre d'années de bénéfices actuels payées par le marché. À comparer au secteur, à l'historique et à la croissance.", "c": "fondamentale", "en": "P/E ratio"}, "peg": {"t": "PEG", "d": "PER divisé par le taux de croissance annuel attendu du BPA (en %). Tente de tenir compte de la croissance dans la valorisation.", "c": "fondamentale", "en": "PEG ratio"}, "rendement-des-benefices": {"t": "Rendement des bénéfices", "d": "Inverse du PER (BPA ÷ cours), parfois comparé au rendement des obligations d'État, une comparaison discutée.", "c": "fondamentale", "en": "Earnings yield"}, "dividende": {"t": "Dividende", "d": "Part des bénéfices distribuée aux actionnaires. Le jour du détachement, le cours baisse en principe d'autant.", "c": "fondamentale", "en": "Dividend"}, "rendement-du-dividende": {"t": "Rendement du dividende", "d": "Dividende par action divisé par le cours. Un rendement très élevé peut signaler un dividende menacé.", "c": "fondamentale", "en": "Dividend yield"}, "taux-de-distribution": {"t": "Taux de distribution", "d": "Part du bénéfice versée en dividendes : dividende ÷ BPA.", "c": "fondamentale", "en": "Payout ratio"}, "sentiment-de-marche": {"t": "Sentiment de marché", "d": "Humeur collective des investisseurs, entre optimisme et peur. Elle peut éloigner durablement les prix de ce que justifient les fondamentaux.", "c": "fondamentale", "en": "Market sentiment"}, "risk-on-risk-off": {"t": "Risk-on / risk-off", "d": "Risk-on : appétit pour le risque (actions, devises cycliques, cryptos recherchées). Risk-off : fuite vers les valeurs refuges.", "c": "fondamentale", "en": "Risk-on / Risk-off"}, "valeur-refuge": {"t": "Valeur refuge", "d": "Actif recherché en période de crise ou d'incertitude : or, obligations d'État solides, dollar, yen, franc suisse (le statut n'est jamais garanti).", "c": "fondamentale", "en": "Safe haven"}, "vix": {"t": "VIX", "d": "Indice de volatilité implicite à 30 jours du S&P 500, tiré des prix des options, surnommé « indice de la peur ». Mouvement journalier typique ≈ VIX ÷ √252.", "c": "fondamentale", "en": "VIX (CBOE Volatility Index)"}, "volatilite-implicite": {"t": "Volatilité implicite", "d": "Volatilité future anticipée par le marché, déduite des prix des options. Elle monte avant les événements incertains et chute souvent après.", "c": "fondamentale", "en": "Implied volatility"}, "cot": {"t": "Rapport COT", "d": "Rapport hebdomadaire de l'autorité américaine des marchés à terme (CFTC) détaillant les positions sur les futures par catégorie d'intervenants.", "c": "fondamentale", "en": "Commitments of Traders report"}, "ratio-put-call": {"t": "Ratio put/call", "d": "Volume d'options de vente rapporté au volume d'options d'achat ; utilisé comme indicateur de sentiment.", "c": "fondamentale", "en": "Put/call ratio"}, "buy-the-rumor": {"t": "Buy the rumor, sell the news", "d": "Adage : un événement attendu est déjà intégré dans les prix ; quand il survient, les prises de bénéfices font souvent baisser le prix.", "c": "fondamentale", "en": "Buy the rumor, sell the news"}, "ebitda": {"t": "EBITDA (EBE)", "d": "Résultat avant intérêts, impôts, dépréciations et amortissements, proche de l'excédent brut d'exploitation. Utilisé dans le ratio valeur d'entreprise / EBITDA.", "c": "fondamentale", "en": "EBITDA"}, "ifo-zew": {"t": "Indices IFO et ZEW", "d": "Enquêtes allemandes de confiance : IFO auprès des entreprises, ZEW auprès des analystes et investisseurs. Suivies comme indicateurs avancés de l'économie de la zone euro.", "c": "fondamentale", "en": "IFO / ZEW indices"}, "gestion-du-risque": {"t": "Gestion du risque", "d": "Ensemble des règles qui limitent les pertes : risque par trade, taille de position, stops, exposition totale, corrélation, limites de perte. Priorité absolue du trader.", "c": "risque", "en": "Risk management"}, "asymetrie-pertes": {"t": "Asymétrie des pertes et des gains", "d": "Pour compenser une perte P, il faut un gain de P ÷ (1 − P) : l'effort de récupération croît très vite avec la perte.", "c": "risque", "en": "Loss recovery asymmetry"}, "risque-par-trade": {"t": "Risque par trade", "d": "Perte maximale prévue si le stop est touché, en pourcentage du capital. Convention prudente : 0,5 à 2 %. À distinguer du montant investi.", "c": "risque", "en": "Risk per trade"}, "regle-des-1-2": {"t": "Règle des 1 à 2 %", "d": "Convention de prudence consistant à ne pas risquer plus de 1 à 2 % du capital par trade. Ce n'est pas une loi démontrée, mais elle protège des séries de pertes.", "c": "risque", "en": "1-2% rule"}, "taille-de-position": {"t": "Taille de position", "d": "Quantité à trader, calculée à partir du risque accepté et de la distance au stop : taille = risque ÷ (distance × valeur unitaire), arrondie vers le bas.", "c": "risque", "en": "Position size"}, "stop-loss": {"t": "Stop loss", "d": "Niveau où l'on coupe une position perdante, placé là où l'hypothèse du trade est invalidée (structure, ATR, temps). Ne jamais l'éloigner.", "c": "risque", "en": "Stop-loss"}, "take-profit": {"t": "Take profit (objectif)", "d": "Niveau où l'on prévoit d'encaisser le gain : niveau technique, multiple du risque, sortie partielle ou trailing stop.", "c": "risque", "en": "Take profit / Profit target"}, "multiple-r": {"t": "R (multiple du risque)", "d": "Unité de mesure d'un trade en multiples du risque initial. Un gain de 2R vaut deux fois la somme risquée.", "c": "risque", "en": "R-multiple"}, "ratio-risque-rendement": {"t": "Ratio risque/rendement", "d": "Rapport entre le gain visé et le risque. Le taux de réussite minimal sans frais est 1 ÷ (1 + R). Un bon ratio seul ne garantit rien.", "c": "risque", "en": "Risk/reward ratio"}, "taux-de-reussite": {"t": "Taux de réussite (win rate)", "d": "Pourcentage de trades gagnants. À lire toujours avec le gain moyen et la perte moyenne : un taux élevé peut cacher une stratégie perdante.", "c": "risque", "en": "Win rate / Hit rate"}, "esperance-mathematique": {"t": "Espérance mathématique", "d": "Gain moyen attendu par trade sur un grand nombre de trades : réussite × gain moyen − échec × perte moyenne, après frais. Condition nécessaire pour gagner à long terme.", "c": "risque", "en": "Expectancy / Expected value"}, "drawdown": {"t": "Drawdown", "d": "Baisse du capital depuis son plus haut précédent. Le drawdown maximal est la pire baisse du pic au creux sur une période.", "c": "risque", "en": "Drawdown"}, "drawdown-maximal": {"t": "Drawdown maximal", "d": "Plus forte baisse observée du pic au creux. Indicateur clé de la « douleur » d'une stratégie ; il faut s'attendre à pire en réel qu'en backtest.", "c": "risque", "en": "Maximum drawdown"}, "serie-de-pertes": {"t": "Série de pertes", "d": "Succession de trades perdants. Inévitable sur un grand nombre de trades, même avec une stratégie gagnante.", "c": "risque", "en": "Losing streak"}, "risque-de-ruine": {"t": "Risque de ruine", "d": "Probabilité de perdre une part du capital telle qu'on ne peut plus continuer. Il augmente très vite avec le risque par trade. Les formules reposent sur des hypothèses irréalistes.", "c": "risque", "en": "Risk of ruin"}, "critere-de-kelly": {"t": "Critère de Kelly", "d": "Formule f = p − (1 − p) ÷ R donnant la fraction du capital qui maximise la croissance à long terme si l'on connaît parfaitement les probabilités. En pratique, trop agressive.", "c": "risque", "en": "Kelly criterion"}, "correlation": {"t": "Corrélation", "d": "Tendance de deux actifs à évoluer ensemble, mesurée entre −1 et +1. Des positions corrélées concentrent le risque ; les corrélations montent souvent en crise.", "c": "risque", "en": "Correlation"}, "diversification": {"t": "Diversification", "d": "Répartition du risque entre des positions peu corrélées, pour réduire la variabilité globale. Elle ne fonctionne que si les corrélations restent faibles.", "c": "risque", "en": "Diversification"}, "couverture": {"t": "Couverture", "d": "Prise d'une position destinée à compenser le risque d'une autre position ou d'une activité.", "c": "risque", "en": "Hedging"}, "limite-de-perte": {"t": "Limites de perte (journalière, hebdomadaire)", "d": "Seuils de perte décidés à l'avance au-delà desquels on cesse de trader pour la journée, la semaine, ou l'on réduit la taille.", "c": "risque", "en": "Daily / weekly loss limit"}, "risque-de-contrepartie": {"t": "Risque de contrepartie", "d": "Risque que la partie avec laquelle on a conclu un contrat (courtier, émetteur) ne puisse pas honorer ses engagements.", "c": "risque", "en": "Counterparty risk"}, "plan-de-trading": {"t": "Plan de trading", "d": "Document écrit qui définit marchés, setups, règles d'entrée et de sortie, taille, limites et routine. Il sert de référence pour juger chaque décision.", "c": "risque", "en": "Trading plan"}, "backtest": {"t": "Backtest", "d": "Application de règles de trading sur des données passées pour en mesurer les résultats, frais et slippage compris.", "c": "risque", "en": "Backtesting"}, "forward-test": {"t": "Forward test", "d": "Application d'une stratégie en temps réel, sur compte démo ou à très petite taille, pour vérifier les résultats du backtest dans des conditions réelles.", "c": "risque", "en": "Forward testing / Paper trading"}, "hors-echantillon": {"t": "Test hors échantillon", "d": "Test d'une stratégie sur des données qui n'ont pas servi à la concevoir. Indispensable pour détecter le surapprentissage.", "c": "risque", "en": "Out-of-sample test"}, "surapprentissage": {"t": "Surapprentissage", "d": "Ajustement excessif d'une stratégie aux données passées : elle « apprend » le bruit et échoue sur des données nouvelles.", "c": "risque", "en": "Overfitting / Curve fitting"}, "biais-du-survivant": {"t": "Biais du survivant", "d": "Erreur consistant à n'étudier que ce qui a « survécu » (actions encore cotées, fonds encore ouverts, traders encore actifs), ce qui surestime les performances.", "c": "risque", "en": "Survivorship bias"}, "biais-d-anticipation": {"t": "Biais d'anticipation (look-ahead)", "d": "Utilisation, dans un test, d'une information qui n'était pas disponible au moment de la décision.", "c": "risque", "en": "Look-ahead bias"}, "biais-de-selection": {"t": "Biais de sélection", "d": "Ne retenir que la période, le marché ou la variante qui donne de bons résultats parmi de nombreux essais.", "c": "risque", "en": "Selection bias / Data snooping"}, "profit-factor": {"t": "Profit factor", "d": "Gains bruts divisés par pertes brutes. Supérieur à 1 : la stratégie gagne ; au-delà de 2 sur longue période, méfiance (surapprentissage ?).", "c": "risque", "en": "Profit factor"}, "ratio-de-sharpe": {"t": "Ratio de Sharpe", "d": "Rendement moyen au-dessus du taux sans risque, divisé par l'écart-type des rendements ; mesure du rendement par unité de risque. S'annualise par √12 pour des données mensuelles.", "c": "risque", "en": "Sharpe ratio"}, "ratio-de-calmar": {"t": "Ratio de Calmar", "d": "Rendement annuel divisé par le drawdown maximal. Variante du raisonnement « rendement par unité de risque », comme le ratio de Sortino qui ne pénalise que la volatilité baissière.", "c": "risque", "en": "Calmar ratio"}, "erreur-type": {"t": "Erreur type et taille d'échantillon", "d": "Incertitude sur une moyenne mesurée : écart-type ÷ √n. L'intervalle de confiance à 95 % vaut environ ± 1,96 erreur type.", "c": "risque", "en": "Standard error / Sample size"}, "setup": {"t": "Setup", "d": "Configuration de marché précise, définie dans le plan de trading, qui autorise une entrée.", "c": "risque", "en": "Setup"}, "peur-avidite": {"t": "Peur et avidité", "d": "Les deux émotions dominantes du trading : la peur fait couper les gains trop tôt ou empêche d'agir ; l'avidité fait grossir les positions et viser trop loin.", "c": "psychologie", "en": "Fear and greed"}, "fomo": {"t": "FOMO", "d": "Peur de rater un mouvement, qui pousse à entrer en retard, sans setup, souvent avec un mauvais ratio risque/rendement.", "c": "psychologie", "en": "Fear Of Missing Out"}, "revenge-trading": {"t": "Revenge trading (trading de revanche)", "d": "Reprendre immédiatement une position, souvent plus grosse, après une perte, pour « se refaire ». Une cause majeure de journées catastrophiques.", "c": "psychologie", "en": "Revenge trading"}, "surtrading": {"t": "Surtrading", "d": "Trader trop souvent, hors de son plan, par ennui, excitation ou pour atteindre un objectif de gain. Multiplie les frais et les erreurs.", "c": "psychologie", "en": "Overtrading"}, "tilt": {"t": "Tilt", "d": "État émotionnel (frustration, colère, euphorie) dans lequel on ne respecte plus ses règles. Terme venu du poker.", "c": "psychologie", "en": "Tilt"}, "biais-cognitif": {"t": "Biais cognitif", "d": "Raccourci de pensée qui fausse le jugement de façon systématique et prévisible, étudié notamment par Kahneman et Tversky.", "c": "psychologie", "en": "Cognitive bias"}, "biais-de-confirmation": {"t": "Biais de confirmation", "d": "Tendance à chercher et retenir les informations qui confirment ce que l'on pense déjà, et à ignorer les autres.", "c": "psychologie", "en": "Confirmation bias"}, "ancrage": {"t": "Ancrage", "d": "Tendance à rester accroché à un chiffre de référence (prix d'achat, ancien sommet) sans rapport avec la situation actuelle.", "c": "psychologie", "en": "Anchoring"}, "aversion-a-la-perte": {"t": "Aversion à la perte", "d": "Une perte pèse psychologiquement plus qu'un gain équivalent (environ deux fois selon la théorie des perspectives). Elle pousse à refuser de couper ses pertes.", "c": "psychologie", "en": "Loss aversion"}, "theorie-des-perspectives": {"t": "Théorie des perspectives", "d": "Théorie de Kahneman et Tversky (1979) décrivant comment les individus évaluent gains et pertes par rapport à un point de référence, avec une aversion marquée pour les pertes.", "c": "psychologie", "en": "Prospect theory"}, "effet-de-disposition": {"t": "Effet de disposition", "d": "Tendance à vendre trop vite les positions gagnantes et à garder les perdantes. Documentée sur des comptes réels (Odean, 1998).", "c": "psychologie", "en": "Disposition effect"}, "exces-de-confiance": {"t": "Excès de confiance", "d": "Surestimation de ses compétences ou de la précision de ses prévisions, souvent après une série de gains.", "c": "psychologie", "en": "Overconfidence"}, "biais-de-recence": {"t": "Biais de récence", "d": "Tendance à surpondérer les événements récents par rapport à l'ensemble des données.", "c": "psychologie", "en": "Recency bias"}, "erreur-du-joueur": {"t": "Erreur du joueur", "d": "Croyance qu'après une série d'événements, l'événement inverse devient « dû ». Des trades indépendants n'ont pas de mémoire.", "c": "psychologie", "en": "Gambler's fallacy"}, "illusion-de-controle": {"t": "Illusion de contrôle", "d": "Croyance de maîtriser des résultats qui dépendent largement du hasard.", "c": "psychologie", "en": "Illusion of control"}, "biais-retrospectif": {"t": "Biais rétrospectif", "d": "Impression, après coup, que l'événement était prévisible. Il fait surestimer la fiabilité des figures et des signaux.", "c": "psychologie", "en": "Hindsight bias"}, "discipline": {"t": "Discipline", "d": "Capacité à appliquer son plan et ses règles, surtout quand on n'en a pas envie. Elle repose sur des règles écrites, une routine et un risque supportable.", "c": "psychologie", "en": "Discipline"}, "routine": {"t": "Routine de trading", "d": "Suite d'actions répétées avant, pendant et après la séance (calendrier, niveaux, journal), qui réduit les décisions prises sous le coup de l'émotion.", "c": "psychologie", "en": "Trading routine"}, "checklist": {"t": "Checklist", "d": "Liste de vérifications à faire avant chaque trade ; un seul « non » signifie : pas de trade.", "c": "psychologie", "en": "Pre-trade checklist"}, "journal-de-trading": {"t": "Journal de trading", "d": "Registre de chaque trade (plan, exécution, résultat, émotion, respect du plan) analysé régulièrement pour repérer ce qui coûte de l'argent.", "c": "psychologie", "en": "Trading journal"}, "amf": {"t": "AMF (Autorité des marchés financiers)", "d": "Autorité française qui régule les marchés financiers, protège les épargnants, publie des listes noires de sites non autorisés et autorise les prestataires de cryptoactifs.", "c": "reglementation", "en": "French Financial Markets Authority"}, "acpr": {"t": "ACPR", "d": "Autorité de contrôle prudentiel et de résolution, adossée à la Banque de France, qui agrée et surveille banques, assurances et entreprises d'investissement.", "c": "reglementation", "en": "French Prudential Supervision and Resolution Authority"}, "esma": {"t": "ESMA", "d": "Autorité européenne des marchés financiers. En 2018, elle a imposé des mesures sur les CFD pour les particuliers (leviers plafonnés, protection contre le solde négatif…), reprises au niveau national.", "c": "reglementation", "en": "European Securities and Markets Authority"}, "regafi": {"t": "REGAFI", "d": "Registre officiel des établissements autorisés à fournir des services bancaires, de paiement ou d'investissement en France, y compris via le passeport européen.", "c": "reglementation", "en": "Register of financial agents (France)"}, "orias": {"t": "ORIAS", "d": "Registre des intermédiaires en assurance, banque et finance (dont les conseillers en investissements financiers).", "c": "reglementation", "en": "French register of intermediaries"}, "liste-noire": {"t": "Liste noire de l'AMF", "d": "Listes publiées par l'AMF de sites et entités proposant sans autorisation des investissements (Forex, CFD, cryptoactifs, biens divers).", "c": "reglementation", "en": "AMF blacklist"}, "passeport-europeen": {"t": "Passeport européen", "d": "Mécanisme permettant à un établissement agréé dans un pays de l'UE de proposer ses services dans les autres pays membres.", "c": "reglementation", "en": "EU passporting"}, "mica": {"t": "MiCA", "d": "Règlement européen encadrant les cryptoactifs et leurs prestataires, applicable depuis fin 2024 avec des périodes transitoires : agrément obligatoire, règles sur les stablecoins.", "c": "reglementation", "en": "Markets in Crypto-Assets Regulation"}, "protection-solde-negatif": {"t": "Protection contre le solde négatif", "d": "Règle européenne pour les clients particuliers en CFD : la perte totale ne peut pas dépasser les fonds déposés sur le compte.", "c": "reglementation", "en": "Negative balance protection"}, "client-professionnel": {"t": "Client professionnel", "d": "Catégorie de client bénéficiant de moins de protections réglementaires (leviers plus élevés autorisés, pas de protection contre le solde négatif sur les CFD). Des critères d'expérience et de patrimoine s'appliquent.", "c": "reglementation", "en": "Professional client"}, "avertissement-cfd": {"t": "Avertissement standardisé sur les CFD", "d": "Mention obligatoire des courtiers en CFD indiquant le pourcentage de leurs clients particuliers qui perdent de l'argent.", "c": "reglementation", "en": "CFD risk warning"}, "segregation-des-fonds": {"t": "Ségrégation des fonds", "d": "Obligation de conserver l'argent des clients séparément de celui du courtier, pour le protéger en cas de faillite.", "c": "reglementation", "en": "Client money segregation"}, "fgdr": {"t": "Garantie des dépôts et des titres (FGDR)", "d": "Fonds de garantie français qui indemnise, dans certaines limites fixées par la réglementation, les clients d'un établissement défaillant (espèces et titres). D'autres pays ont leur propre mécanisme.", "c": "reglementation", "en": "Deposit and investor guarantee scheme"}, "dic": {"t": "DIC (document d'informations clés)", "d": "Document réglementaire de quelques pages décrivant un produit financier : objectifs, risques, scénarios de performance, coûts.", "c": "reglementation", "en": "KID (Key Information Document)"}, "ucits": {"t": "UCITS (OPCVM)", "d": "Cadre réglementaire européen des fonds ouverts au public (organismes de placement collectif en valeurs mobilières), avec des règles de diversification et de protection.", "c": "reglementation", "en": "UCITS"}, "cto": {"t": "CTO (compte-titres ordinaire)", "d": "Compte pouvant détenir presque tous les titres cotés, sans plafond ni durée, aux gains imposés selon le régime de droit commun.", "c": "reglementation", "en": "Ordinary securities account"}, "pea": {"t": "PEA (plan d'épargne en actions)", "d": "Enveloppe fiscale pour les actions européennes et les fonds éligibles, avec un plafond de versements et une exonération d'impôt sur le revenu (hors prélèvements sociaux) après une durée minimale. Exclut CFD, Forex, dérivés, turbos, cryptoactifs.", "c": "reglementation", "en": "French equity savings plan (PEA)"}, "plus-value": {"t": "Plus-value / moins-value", "d": "Différence positive (plus-value) ou négative (moins-value) entre prix de cession et prix d'acquisition, frais compris. Imposée sur le solde net annuel ; les moins-values sont reportables pendant une durée limitée.", "c": "reglementation", "en": "Capital gain / loss"}, "pfu": {"t": "PFU (prélèvement forfaitaire unique)", "d": "Imposition forfaitaire par défaut des revenus du capital (impôt sur le revenu + prélèvements sociaux). Ses taux sont fixés par la loi et évoluent : à vérifier sur impots.gouv.fr.", "c": "reglementation", "en": "Flat tax"}, "bareme-progressif": {"t": "Barème progressif (option)", "d": "Alternative au PFU : imposition des revenus du capital selon les tranches de l'impôt sur le revenu, sur option globale pour l'année.", "c": "reglementation", "en": "Progressive income tax scale (option)"}, "prelevements-sociaux": {"t": "Prélèvements sociaux", "d": "Contributions sociales prélevées sur les revenus du capital, y compris dans un PEA après la durée minimale. Taux fixés par la loi, susceptibles d'évoluer.", "c": "reglementation", "en": "Social contributions"}, "prix-moyen-pondere": {"t": "Prix moyen pondéré d'acquisition", "d": "Méthode française de calcul du prix de revient de titres identiques achetés en plusieurs fois : coût total ÷ nombre de titres.", "c": "reglementation", "en": "Weighted average cost"}, "ifu": {"t": "IFU (imprimé fiscal unique)", "d": "Récapitulatif annuel des revenus et cessions envoyé par les établissements financiers établis en France, pour aider à remplir la déclaration de revenus.", "c": "reglementation", "en": "Annual tax statement"}, "compte-etranger": {"t": "Déclaration des comptes à l'étranger", "d": "Obligation pour un résident fiscal français de déclarer chaque année les comptes (bancaires, de courtage, d'actifs numériques) ouverts, détenus, utilisés ou clos à l'étranger, même vides. Amendes par compte non déclaré.", "c": "reglementation", "en": "Foreign account reporting"}, "bofip": {"t": "BOFiP", "d": "Bulletin officiel des finances publiques : base documentaire où l'administration fiscale publie sa doctrine.", "c": "reglementation", "en": "Official tax doctrine (France)"}, "societe-clone": {"t": "Société clone", "d": "Escroquerie qui usurpe le nom, le logo, voire le numéro d'agrément d'un établissement réellement autorisé.", "c": "reglementation", "en": "Clone firm"}, "arnaque-ponzi": {"t": "Pyramide de Ponzi", "d": "Escroquerie qui verse des « rendements » aux premiers investisseurs avec l'argent des nouveaux, sans activité réelle ; elle s'effondre quand les dépôts ralentissent.", "c": "reglementation", "en": "Ponzi scheme"}, "arnaque-au-recouvrement": {"t": "Arnaque au recouvrement", "d": "Seconde escroquerie visant des victimes d'une première arnaque, à qui l'on promet de récupérer leurs fonds contre paiement.", "c": "reglementation", "en": "Recovery scam"}, "taxe-transactions": {"t": "Taxe sur les transactions financières", "d": "Taxe française prélevée à l'achat d'actions de grandes sociétés françaises, au-delà d'un seuil de capitalisation. Taux et liste des sociétés concernées : à vérifier.", "c": "reglementation", "en": "Financial Transaction Tax (France)"}, "bull-bear": {"t": "Bull / bear", "d": "Bull (taureau) : acheteur ou marché haussier. Bear (ours) : vendeur ou marché baissier. On parle de bull market et de bear market.", "c": "jargon", "en": "Bull / Bear"}, "bullish-bearish": {"t": "Bullish / bearish", "d": "Haussier / baissier, pour qualifier une opinion, une configuration ou un marché.", "c": "jargon", "en": "Bullish / Bearish"}, "long": {"t": "Long / short", "d": "Être long : être acheteur (gagner à la hausse). Être short : être vendeur (gagner à la baisse).", "c": "jargon", "en": "Long / Short"}, "ath": {"t": "ATH / ATL", "d": "Plus haut historique (ATH) et plus bas historique (ATL) d'un actif.", "c": "jargon", "en": "All-Time High / All-Time Low"}, "hodl": {"t": "HODL", "d": "Jargon crypto issu d'une faute de frappe de « hold » : conserver ses cryptoactifs quoi qu'il arrive, sans vendre dans les baisses.", "c": "jargon", "en": "HODL (Hold On for Dear Life)"}, "scalp": {"t": "Scalp / scalping", "d": "Trade très court (secondes à minutes) visant un tout petit gain ; le scalping est le style qui en enchaîne beaucoup.", "c": "jargon", "en": "Scalp / Scalping"}, "day-trading": {"t": "Day trading", "d": "Style de trading où toutes les positions sont ouvertes et fermées dans la journée.", "c": "jargon", "en": "Day trading"}, "swing-trading": {"t": "Swing trading", "d": "Style de trading visant des mouvements de quelques jours à quelques semaines, souvent compatible avec une activité professionnelle.", "c": "jargon", "en": "Swing trading"}, "position-trading": {"t": "Position trading", "d": "Style de trading à horizon de plusieurs semaines à plusieurs mois, proche de l'investissement, avec des stops larges.", "c": "jargon", "en": "Position trading"}, "breakout": {"t": "Breakout", "d": "Cassure d'un niveau ou d'une figure, souvent utilisée comme signal d'entrée.", "c": "jargon", "en": "Breakout"}, "fakeout": {"t": "Fakeout", "d": "Jargon pour une fausse cassure.", "c": "jargon", "en": "Fakeout"}, "dip": {"t": "Dip / BTFD", "d": "Dip : repli temporaire. « Buy the dip » : acheter les replis. Dans une vraie tendance baissière, cela revient à « attraper un couteau qui tombe ».", "c": "jargon", "en": "Buy the dip"}, "rally-selloff": {"t": "Rally / sell-off / krach", "d": "Rally : forte hausse. Sell-off : vague de ventes. Krach : chute brutale et importante des marchés.", "c": "jargon", "en": "Rally / Sell-off / Crash"}, "pnl": {"t": "PnL (P&L)", "d": "Profit and Loss : gain ou perte, latent (position ouverte) ou réalisé (position fermée).", "c": "jargon", "en": "Profit and Loss"}, "edge": {"t": "Edge (avantage)", "d": "Avantage statistique d'une stratégie, qui se traduit par une espérance positive après frais, mesurée sur un échantillon suffisant.", "c": "jargon", "en": "Edge"}, "fud": {"t": "FUD", "d": "Peur, incertitude et doute : rumeurs ou informations négatives (parfois volontairement diffusées) qui poussent à vendre.", "c": "jargon", "en": "Fear, Uncertainty and Doubt"}, "pump-and-dump": {"t": "Pump and dump", "d": "Manipulation consistant à faire monter artificiellement un actif peu liquide (promotion, rumeurs) pour revendre aux acheteurs attirés. Illégale.", "c": "jargon", "en": "Pump and dump"}, "whale": {"t": "Whale (baleine)", "d": "Intervenant détenant une position très importante, capable de faire bouger un marché, notamment sur les cryptoactifs.", "c": "jargon", "en": "Whale"}, "chasse-aux-stops": {"t": "Chasse aux stops", "d": "Mouvement de prix qui atteint une zone où de nombreux stops sont placés, puis repart. L'idée d'une manipulation délibérée est souvent invoquée mais rarement démontrable.", "c": "jargon", "en": "Stop hunt"}, "compte-demo": {"t": "Compte démo", "d": "Compte de trading avec de l'argent fictif, pour apprendre une plateforme et tester une stratégie. Exécution souvent idéalisée et absence de pression émotionnelle : ses résultats sont nécessaires, pas suffisants.", "c": "jargon", "en": "Demo account / Paper trading account"}, "dca": {"t": "DCA (investissement programmé)", "d": "Investir un montant fixe à intervalles réguliers, quel que soit le prix, pour lisser le prix d'achat.", "c": "jargon", "en": "Dollar-Cost Averaging"}, "bagholder": {"t": "Bagholder", "d": "Personne qui conserve une position fortement perdante, souvent achetée au sommet, en espérant un retour au prix d'achat.", "c": "jargon", "en": "Bagholder"}, "rekt": {"t": "Rekt", "d": "Argot pour un trader qui a subi une perte très lourde, souvent par liquidation.", "c": "jargon", "en": "Rekt (wrecked)"}, "risk-reward-rr": {"t": "R:R", "d": "Notation courante du ratio risque/rendement (par exemple 1:3).", "c": "jargon", "en": "Risk:Reward"}, "yolo": {"t": "YOLO", "d": "Jargon pour une prise de risque démesurée sur une seule position, à l'opposé de toute gestion du risque.", "c": "jargon", "en": "You Only Live Once"}};
